# region: intake
def intake(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: digest
def digest(xs, limit=12):
    return [v if v <= limit else limit for v in xs]

# region: shape
def shape(xs, offset=1):
    return [v - offset for v in xs]

# region: sift
def sift(xs, offset=1):
    return [v + offset for v in xs]

# region: render
def render(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (max(xs) - min(xs)) if xs else 0}

# region: fold
def fold(summary, bar=2):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return fold(render(sift(shape(digest(intake(raw))))))

